<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {api} from '../../api/http'
import {useControlledRequest} from '../../api/controlled'
import {useAuthStore} from '../../stores/auth'
import IncomingReferencePicker from '../quality/IncomingReferencePicker.vue'
import ReadReference from '../master/ReadReference.vue'
import FinishedReferencePicker from './FinishedReferencePicker.vue'
import {definitions,labels,status,commandBody,commands,canAct,inboundCreateBody,type Row,type Command} from './model'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),request=useControlledRequest(),{error,busy,conflict}=request,record=ref<Row>({}),form=ref<Row>({}),action=ref(''),password=ref(''),signatureOpen=ref(false)
const linkedInspection=ref<Row|null>(null),linkedInspectionError=ref('')
const def=computed(()=>definitions[String(route.meta.resource)]!),create=computed(()=>route.meta.mode==='create'),command=computed<Command|undefined>(()=>create.value?def.value.create:action.value==='RECEIVE_SAMPLE'?commands.reason:def.value.actions[action.value]?.command),actions=computed(()=>Object.entries(def.value.actions).filter(([key,a])=>canAct(record.value,key,auth.can(a.permission)))),sample=computed(()=>record.value.sample as Row|undefined),resultItems=computed(()=>record.value.summary?.items??[])
const facts=computed(()=>['mainBatchId','productId','inboundRequestId','inspectionRequestId','materialLotId','quantity','unitId','receivingParty','samplingLocation','samplingMethod','qcSpecificationVersionId','generationNo','createdBy','createdAt','submittedBy','submittedAt','confirmedBy','confirmedAt','acceptedBy','acceptedAt','sampledBy','sampledAt','generatedBy','generatedAt','approvedBy','approvedAt'].filter(k=>record.value[k]!=null)),signed=computed(()=>command.value?.signed),source=computed(()=>action.value==='RECEIVE_SAMPLE'?sample.value!:record.value)
const refFields=new Set(['mainBatchId','locationId','unitId'])
function start(key:string){request.clear();action.value=key;form.value={};password.value=''}
async function load(){request.clear();linkedInspection.value=null;linkedInspectionError.value='';try{record.value=create.value?{}:await api({url:def.value.api+'/'+route.params.id});if(!create.value){const row=record.value;record.value={...row,mainBatchId:row.mainBatchId??row.summary?.mainBatchId??row.sample?.mainBatchId,materialLotId:row.materialLotId??row.summary?.materialLotId,qcSpecificationVersionId:row.qcSpecificationVersionId??row.summary?.qcSpecificationVersionId};}if(!create.value&&route.meta.resource==='inbound'&&auth.can('qms:finished-request:view')){try{const list=await api<{items:Row[]}>({url:definitions.requests!.api,params:{mainBatchId:record.value.mainBatchId,page:0,size:20}});linkedInspection.value=list.items.find(r=>String(r.inboundRequestId)===String(record.value.id))??null}catch{linkedInspectionError.value='关联请验单暂不可读取'}}form.value={...(route.query.mainBatchId?{mainBatchId:String(route.query.mainBatchId)}:{}),...(route.query.inboundRequestId?{inboundRequestId:String(route.query.inboundRequestId)}:{})};action.value=''}catch(e){await request.failure(e)}}
onBeforeRouteLeave(()=>!command.value||!Object.values(form.value).some(Boolean)||window.confirm('离开将放弃未保存的输入，是否继续？'))
function buildBody(){return create.value&&route.meta.resource==='inbound'?inboundCreateBody(form.value):commandBody(command.value!,form.value,create.value?undefined:source.value.versionNo)}
async function prepare(){try{buildBody();if(signed.value)signatureOpen.value=true;else await save()}catch(e){await request.failure(e)}}
async function save(){busy.value=true;try{const body=buildBody();if(signed.value){if(!password.value)throw Error('请输入签名密码');const objectId=record.value.id+':'+record.value.versionNo;const r=await api<{reauthToken:string}>({url:'/auth/reauth',method:'POST',data:{objectType:signed.value.type,objectId,recordVersion:record.value.versionNo,meaning:signed.value.meaning,credential:password.value}});body.signature={reauthToken:r.reauthToken}}
const url=create.value?def.value.api:action.value==='RECEIVE_SAMPLE'?'/samples/'+sample.value!.id+'/receive':def.value.api+'/'+record.value.id+'/'+def.value.actions[action.value]!.path;const a=action.value,row=await request.mutate<Row>(url,'POST',body,create.value?undefined:source.value.versionNo);form.value={};signatureOpen.value=false;action.value='';if(create.value)await router.replace(def.value.path+'/'+row.id);else if(a==='SAMPLE')await router.push('/finished/sampling/'+row.id);else if(a==='GENERATE_REPORT')await router.push('/finished/reports/'+row.id);else await load()}catch(e){await request.failure(e)}finally{busy.value=false;password.value=''}}
function refField(field:string){return field.endsWith('By')?'userId':field==='inspectionRequestId'?'finishedInspectionRequestId':field}
watch(()=>route.fullPath,()=>void load(),{immediate:true})
</script><template><main :data-ui-template="create?'T2':'T3'" class="admin-page master-page finished-detail"><header class="admin-page-header"><div><a-button type="link" @click="router.push({path:route.meta.resource==='inbound'&&route.query.receivingOnly==='true'?'/finished/receiving':def.path,query:route.query})">← 返回列表</a-button><h1>{{create?'新增'+def.title:record[def.number]??def.title}}</h1><p>{{def.title}} <a-tag v-if="!create">{{status[record.status]??'取样已记录'}}</a-tag><a-tag v-if="record.overallConclusion" :color="record.overallConclusion==='PASS'?'green':'red'">{{status[record.overallConclusion]}}</a-tag></p></div><a-space wrap v-if="!create"><a-button v-for="[key,a] in actions" :key="key" :type="key==='CONFIRM'||key==='APPROVE'?'primary':'default'" @click="start(key)">{{a.title}}</a-button><a-button @click="load">刷新</a-button></a-space></header><a-alert v-if="error" :message="error" type="error" show-icon/><a-alert v-if="conflict" message="记录已变化，请刷新后重新核对。" type="warning"/>
<a-card v-if="!create" title="业务信息" class="form-section"><div class="master-form"><label v-for="field in facts" :key="field"><span class="form-field-label">{{field==='inboundRequestId'?'关联成品入库申请':labels[field]}}</span><ReadReference v-if="field.endsWith('Id')||field.endsWith('By')" :field="refField(field)" :value="record[field]" fallback="暂无可读业务名称" :name="field==='mainBatchId'?record.batch?.batchNo:field==='materialLotId'?record.lot?.lotNo:undefined"/><span v-else>{{record[field]}}</span></label></div><p v-if="record.reason">备注 / 原因：{{record.reason}}</p><a-space wrap><a-button v-if="record.materialLotId&&auth.can('wms:inventory:view')" @click="router.push('/wms/material-lots/'+record.materialLotId)">成品批次与库存追溯</a-button><a-button v-if="record.mainBatchId&&auth.can('qa:batch-review')" @click="router.push('/qa/batches/'+record.mainBatchId+'/review')">QA批审核</a-button><a-button v-if="record.inspectionRequestId&&auth.can('qms:finished-request:view')" @click="router.push('/finished/requests/'+record.inspectionRequestId)">来源成品请验单</a-button></a-space></a-card>
<a-card v-if="linkedInspection" title="关联成品请验草稿 / 请验单" class="form-section"><a-button type="link" @click="router.push('/finished/requests/'+linkedInspection.id)">{{linkedInspection.inspectionRequestNo}}</a-button><a-tag>{{status[linkedInspection.status]}}</a-tag><p>仓库确认接收后才能提交请验和执行QC。</p></a-card><a-alert v-if="linkedInspectionError" type="warning" :message="linkedInspectionError" class="form-section"/><a-alert v-if="route.meta.resource==='requests'&&record.status==='DRAFT'" type="info" message="仓库确认接收后才能提交请验和执行QC。" class="form-section"/>
<a-card v-if="record.samplingRecords?.length" title="取样记录与样品" class="form-section"><a-table :data-source="record.samplingRecords" :columns="[{title:'取样编号',dataIndex:'samplingNo'},{title:'样品',key:'sample'},{title:'位置',dataIndex:'samplingLocation'},{title:'数量',dataIndex:'quantity'},{title:'取样时间',dataIndex:'sampledAt'},{title:'操作',key:'open'}]" row-key="id" :pagination="false" :scroll="{x:750}"><template #bodyCell="{column,record:r}"><ReadReference v-if="column.key==='sample'" field="productionSampleId" :value="r.sampleId"/><a-button v-else-if="column.key==='open'&&auth.can('qms:finished-sampling:view')" type="link" @click="router.push('/finished/sampling/'+r.id)">查看取样与样品</a-button></template></a-table></a-card>
<a-card v-if="sample" title="生成的成品样品" class="form-section"><div class="master-form"><label><span class="form-field-label">样品编号</span><span>{{sample.sampleNo}}</span></label><label><span class="form-field-label">样品类型</span><span>{{status[sample.sampleType]}}</span></label><label><span class="form-field-label">样品状态</span><span>{{({COLLECTED:'已取样',RECEIVED:'已接收',IN_TEST:'检验中'} as Record<string,string>)[sample.status]??sample.status}}</span></label><label><span class="form-field-label">取样数量</span><span>{{sample.quantity}} <ReadReference field="unitId" :value="sample.unitId"/></span></label></div><a-space><a-button v-if="sample.allowedActions?.includes('RECEIVE')&&auth.can('qms:sample:receive')" @click="start('RECEIVE_SAMPLE')">QC接收样品</a-button><a-button v-if="['RECEIVED','IN_TEST'].includes(sample.status)&&auth.can('qms:test:record')" @click="router.push({path:'/quality/production-tests/create',query:{mainBatchId:sample.mainBatchId,sampleId:sample.id}})">执行成品检验</a-button></a-space></a-card>
<a-card v-if="record.reports?.length" title="报告历史" class="form-section"><div v-for="r in record.reports" :key="r.id"><a-button v-if="auth.can('qms:finished-report:view')" type="link" @click="router.push('/finished/reports/'+r.id)">{{r.reportNo}}</a-button><span>{{status[r.status]}} · {{status[r.overallConclusion]}} · {{r.generatedAt}}</span></div></a-card>
<a-card v-if="record.summary" title="检验项目与结果" class="form-section"><p>汇总当前请验冻结的质量标准与原始检验结果，综合结论：<a-tag :color="record.overallConclusion==='PASS'?'green':'red'">{{status[record.overallConclusion]}}</a-tag></p><a-table :data-source="resultItems" :columns="[{title:'检验项目',key:'item'},{title:'标准要求',key:'standard'},{title:'实际结果',key:'result'},{title:'单位',key:'unit'},{title:'判定',key:'conclusion'}]" :row-key="(r:Row)=>r.standard.specificationItemId" :pagination="false" :scroll="{x:800}"><template #bodyCell="{column,record:r}"><span v-if="column.key==='item'">{{r.standard.itemName??r.standard.testCode}}</span><span v-else-if="column.key==='standard'">{{r.standard.textAcceptanceCriteria??[r.standard.lowerLimit??'—',r.standard.upperLimit??'—'].join(' ～ ')}}</span><span v-else-if="column.key==='result'">{{r.effectiveResult?.resultNumeric??r.effectiveResult?.resultText??'—'}}</span><ReadReference v-else-if="column.key==='unit'" field="unitId" :value="r.standard.unitId"/><a-tag v-else-if="column.key==='conclusion'" :color="r.conclusion==='PASS'?'green':'red'">{{status[r.conclusion]??'未检验'}}</a-tag></template></a-table><details><summary>原始结果及修订证据</summary><section v-for="r in resultItems" :key="r.standard.specificationItemId"><h3>{{r.standard.itemName??r.standard.testCode}}</h3><p v-for="result in r.originalResults" :key="result.id">结果引用 {{result.id}} · 修订 {{result.revisionNo}} · {{result.resultNumeric??result.resultText}} · {{status[result.resultConclusion]}} · {{result.recordedAt}}</p></section></details></a-card>
<a-card v-if="record.reviews?.length" title="独立复核与电子签名" class="form-section"><p v-for="r in record.reviews" :key="r.id"><ReadReference field="userId" :value="r.reviewedBy"/> · {{r.reviewedAt}} · 签名引用 {{r.signatureId}}</p></a-card>
<a-card v-if="command" :title="create?'基本信息':action==='RECEIVE_SAMPLE'?'QC接收样品':def.actions[action]?.title" class="form-section"><form @submit.prevent="prepare"><div class="master-form"><label v-for="field in command.fields" :key="field" :class="{'form-full-row':['reason','samplingMethod'].includes(field)}"><span class="form-field-label">{{labels[field]}} *</span><FinishedReferencePicker v-if="field==='inboundRequestId'" v-model="form[field]" :disabled="busy"/><IncomingReferencePicker v-else-if="refFields.has(field)" :field="field" v-model="form[field]" :context="form" :query-filters="field==='mainBatchId'?{status:String(route.meta.resource)==='shipments'?'QA_RELEASED':'PRODUCTION_COMPLETED'}:undefined" :disabled="busy" required :input-label="labels[field]"/><select v-else-if="field==='sampleType'" v-model="form[field]" aria-label="样品类型" class="master-native-input" required><option v-for="s in ['TEST_SAMPLE','RETENTION_SAMPLE','RETEST_SAMPLE','OTHER_APPROVED']" :key="s" :value="s">{{status[s]}}</option></select><textarea v-else-if="['reason','samplingMethod'].includes(field)" v-model="form[field]" class="master-native-input" :aria-label="labels[field]" required maxlength="1000" :disabled="busy"/><input v-else v-model="form[field]" class="master-native-input" :aria-label="labels[field]" required :maxlength="field==='receivingParty'||field==='samplingLocation'?200:80" :disabled="busy"/></label><template v-if="create&&route.meta.resource==='inbound'&&auth.can('qms:finished-request:create')"><label class="form-full-row"><span class="form-field-label">成品请验</span><span><input v-model="form.createInspectionDraft" type="checkbox" aria-label="同时生成成品请验草稿" :disabled="busy"/> 同时生成成品请验草稿</span></label><label v-if="form.createInspectionDraft"><span class="form-field-label">成品请验单号 *</span><input v-model="form.inspectionRequestNo" class="master-native-input" aria-label="成品请验单号" required maxlength="80" :disabled="busy"/></label><p v-if="form.createInspectionDraft" class="form-full-row">仅生成关联草稿；仓库确认接收后才能提交请验和执行QC。</p></template></div><a-space class="finished-actions"><a-button :disabled="busy" @click="form={};action='';create&&router.push(def.path)">取消</a-button><a-button type="primary" html-type="submit" :loading="busy" :disabled="conflict">{{signed?'核对并签名':'提交'}}</a-button></a-space></form></a-card><details v-if="!create" class="finished-metadata"><summary>记录元数据与审计</summary><p>记录引用 {{record.id}} · 记录版本 {{record.versionNo}} · 签名引用 {{record.signatureId??'—'}}</p><p v-if="record.sourceDigest||record.evidenceDigest">证据摘要 {{record.sourceDigest??record.evidenceDigest}}</p><a-button v-if="auth.can('audit:view')" type="link" @click="router.push('/audit')">审计追踪</a-button><a-button v-if="record.mainBatchId&&auth.can('trace:view')" type="link" @click="router.push({path:'/trace',query:{mainBatchId:record.mainBatchId}})">完整追溯</a-button></details><a-modal v-model:open="signatureOpen" title="电子签名确认" ok-text="签名并提交" :confirm-loading="busy" @ok="save" @cancel="password=''"><p>签名绑定本次业务动作及当前记录版本，请核对原因和原始证据。</p><label><span>签名密码</span><a-input-password v-model:value="password" aria-label="签名密码" autocomplete="current-password"/></label></a-modal></main></template><style scoped>.finished-detail .master-form{max-width:1100px}.finished-actions{margin-top:16px}.finished-metadata{font-size:12px;color:#667085;overflow-wrap:anywhere}details{margin-top:16px}</style>
